import{_ as e,o as a,c as t,aj as s}from"./chunks/framework.BdtAaXf2.js";const r="/assets/zh.kSntTvOy.png",i="/assets/ReActAgent.Dc9tS1RT.png",o="/assets/WorkflowAgent.JudX0BFE.png",g="/assets/image-20260428144652593.D_Td4W1x.png",m="/assets/image-20260428144404343.htqvrB07.png",p="/assets/image-20260423095322174.Cs8lYr4r.png",l="/assets/image-20260423100018398.B5snzhvY.png",w="/assets/image-20260423140104941.DAZ4qOOe.png",c="/assets/image-20260423135651974.DeLr-H9E.png",u="/assets/image-20260423135828213.We934epo.png",h="/assets/image-20260423135845085.mChs--Lr.png",d="/assets/image-20260423140234222.Dw4Yl4xW.png",A="/assets/image-20260423140311633.BFATlYHz.png",S="/assets/image-20260423140336187.BUFH4mGQ.png",_="/assets/image-20260423140406263.BaSVOqPm.png",J="/assets/image-20260423140423948.D9qlWIyt.png",k="/assets/image-20260423140507426.D9h26Jil.png",b="/assets/image-20260423141333085.Dhp2iiUL.png",f="/assets/image-20260423142209473.CCTJF5aX.png",q="/assets/image-20260423142421574.CcDlpx9c.png",P="/assets/image-20260423142454316.CgTcD6Eh.png",R="/assets/image-20260423142517587.BALW8Nhn.png",I="/assets/image-20260423144337786.CCyKTaMC.png",C="/assets/image-20260423144352415.D0sWeK1A.png",x="/assets/image-20260423145550856.Di9CcEx9.png",E="/assets/image-20260423145053102.DXvpEP5l.png",T="/assets/image-20260423145139940.BHUxr8ie.png",L="/assets/image-20260423145221387.C0Sd8dYR.png",H=JSON.parse('{"title":"利用 JiuwenSwarm AgentSwarm 打造自动化研发团队","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/基于 JiuwenSwarm AgentSwarm 构建自动化研发团队/基于 JiuwenSwarm AgentSwarm 构建自动化研发团队.md","filePath":"AI人工智能/基于 JiuwenSwarm AgentSwarm 构建自动化研发团队/基于 JiuwenSwarm AgentSwarm 构建自动化研发团队.md","lastUpdated":1779246105000,"__rawMarkdown":"# 利用 JiuwenSwarm AgentSwarm 打造自动化研发团队\\n\\n> 本文介绍如何通过 **JiuwenSwarm AgentSwarm** 构建自动化研发团队，实现字幕软件开发、AtomGit Issue/PR 智能处理与飞书文档同步。\\n\\n## 目录\\n\\n- [JiuwenSwarm 平台概述](#JiuwenSwarm-平台概述)\\n  - [系统架构](#系统架构)\\n  - [预置智能体类型](#预置智能体类型)\\n- [什么是 AgentSwarms](#什么是-AgentSwarms)\\n- [飞书群中添加机器人](#飞书群中添加机器人)\\n- [开启 AgentSwarms](#开启-AgentSwarms)\\n- [工作流程](#工作流程)\\n- [自动处理 PR](#自动处理-pr)\\n  - [模拟生成 PR](#模拟生成-pr)\\n- [自动生成飞书日报](#自动生成飞书日报)\\n  - [JiuwenSwarm 接入飞书 lark-cli](#JiuwenSwarm-接入飞书-lark-cli)\\n  - [授权给 lark-cli](#授权给-lark-cli)\\n- [总结](#总结)\\n\\n## JiuwenSwarm 平台概述\\n\\n**openJiuwen** 是一个开源的 AI Agent 平台，其核心目标是为开发者提供灵活、强大且易于使用的 AI Agent 开发与运行环境。\\n\\n借助这一平台，开发者能够迅速搭建起可处理各种复杂度的 AI Agent，实现多个 Agent 之间的协作互动，从而高效地打造出生产级别的可靠 AI Agent。同时，该平台也帮助企业和个人用户快速构建自己的 AI Agent 系统或平台，促进商用级 Agentic AI 技术的广泛落地应用。\\n\\n### 系统架构\\n\\nopenJiuwen 的整体架构由三大核心模块构成：**openJiuwen Core**、**openJiuwen Studio** 以及 **openJiuwen Ops**。\\n\\n![系统架构图](assets/zh.png)\\n\\n在开发阶段，openJiuwen 提供了 Agent 编排与构建能力，让开发者能够快速创建 Agent 并进行高效开发。\\n\\n### 预置智能体类型\\n\\n目前，openJiuwen 提供了两种预置智能体类型，为用户提供丰富的功能和灵活的开发选项，以适应不同场景下的智能化需求：\\n\\n- **ReActAgent**：这是一种基于 ReAct（推理 + 行动）规划范式的 Agent。它通过「思考 → 行动 → 观察」的循环迭代过程来完成任务。ReActAgent 拥有强大的多轮推理和自我纠错能力，能够进行动态决策并灵活适应环境变化，特别适合那些需要复杂推理和策略调整的任务场景。\\n\\n  ![ReActAgent 架构](assets/ReActAgent.png)\\n\\n- **Workflow Agent**：这是一种面向多步骤任务的流程自动化 Agent，严格按照用户预设的任务流程来高效执行复杂任务。它强调通过预定义流程实现任务的规范化与高效执行，适用于任务结构清晰、能够分解为多个明确步骤的场景。\\n\\n  ![Workflow Agent 架构](assets/WorkflowAgent.png)\\n\\n## JiuwenSwarm 概述\\n\\n​ 它是一款基于 openJiuwen Python 框架开发的 AI Agent，天然拥有良好的生态兼容性和扩展能力。在模型接入方面，JiuwenSwarm 支持华为云 MaaS 等主流模型平台，用户只需简单配置即可调用华为云的模型服务。此外，JiuwenSwarm 已实现与小艺开放平台的无缝对接，华为手机用户可以通过小艺直接唤醒并使用 JiuwenSwarm，享受随叫随到的智能服务。\\n\\n![](assets/image-20260428144652593.png)\\n\\n## 什么是 AgentSwarms\\n\\n​ 从 Prompt Engineering（提示工程）、Context Engineering（语境工程）演进至当下备受瞩目的 Harness Engineering（驾驭工程），AI 领域的工程范式始终处于高速迭代之中。\\n\\n​ 目前，针对单一智能体的“驾驭与治理”已逐渐成为行业标配，但如何让多个智能体仿若一支精锐团队，实现自主分工、高效沟通与无缝协作，依然是横亘在行业面前的核心挑战。\\n\\n​ 恰逢这一趋势风口，获华为支持的 openJiuwen 社区正式发布了最新的 JiuwenSwarm 版本。该版本重磅新增了对 AgentSwarm 多智能体协同能力的支持，并前瞻性地提出 Harness Engineering 的下一个演进方向是“Coordination Engineering（协同工程）”，成功将多智\\n\\n能体自主协同从抽象的概念转化为可直接落地的实战场景。\\n\\n![](assets/image-20260428144404343.png)\\n\\n## 飞书群中添加机器人\\n\\n> **参考文档**：[飞书频道配置指南](https://gitcode.com/openJiuwen/JiuwenSwarm/blob/develop/docs/zh/%E9%A2%91%E9%81%93.md#%E9%A3%9E%E4%B9%A6)\\n\\n在飞书群聊中，添加创建好的飞书机器人后，用户可以直接在群聊中对话。飞书机器人负责接收用户的指令，并代理用户与 **JiuwenSwarm** 进行交互。\\n\\n![飞书群机器人](assets/image-20260423095322174.png)\\n\\n## 开启 AgentSwarms\\n\\n在飞书对话中，输入以下命令即可主动开启 AgentSwarms 模式：\\n\\n```bash\\n/mode team\\n```\\n\\n然后可以直接输入需求来安排任务。\\n\\n![开启 AgentSwarms 模式](assets/image-20260423100018398.png)\\n\\n## 工作流程\\n\\n整体工作流程如下图所示：\\n\\n![工作流程概览](assets/image-20260423140104941.png)\\n\\nAgentSwarms 的标准协作流程包含以下步骤：\\n\\n1. **Leader** 接收到任务后，开始拆分任务\\n2. **Leader** 布置任务\\n3. **Teammate** 认领任务\\n4. **Teammate** 执行任务\\n5. **Leader** 和 **Teammate** 之间相互通信\\n6. **Teammate** 汇报任务进度\\n7. **Leader** 总结工作\\n\\n以下是各阶段的操作截图：\\n\\n**步骤 1-2：任务拆分与布置**\\n\\n![Leader 拆分任务](assets/image-20260423135651974.png)\\n\\n**步骤 3-4：任务认领与执行**\\n\\n![Teammate 执行任务](assets/image-20260423135828213.png)\\n\\n![任务执行中](assets/image-20260423135845085.png)\\n\\n![任务执行过程](assets/image-20260423140234222.png)\\n\\n![代码生成](assets/image-20260423140311633.png)\\n\\n![持续执行](assets/image-20260423140336187.png)\\n\\n**步骤 5-6：通信与汇报**\\n\\n![通信汇报](assets/image-20260423140406263.png)\\n\\n![任务汇报](assets/image-20260423140423948.png)\\n\\n**步骤 7：总结**\\n\\n![Leader 总结](assets/image-20260423140507426.png)\\n\\n### 结束\\n\\n当所有任务完成后，Leader 会输出最终的总结报告。\\n\\n![任务结束](assets/image-20260423141333085.png)\\n\\n## 自动处理 PR\\n\\n> **工具地址**：[https://atomgit.com/GitCode/ag-cli](https://atomgit.com/GitCode/ag-cli)\\n\\n> 可以在 **JiuwenSwarm** 中配置 **AtomGit** 的 CLI 工具，设置监听后自动处理审核和合并 PR。\\n>\\n> ⚠️ **注意**：监听需要提供公网域名，用来接收 AtomGit 的 Webhooks 通知。\\n\\n**AtomGit** 提供了 `ag-cli` 工具，可以在 **JiuwenSwarm** 中接入。接入后，**AgentSwarms** 即可通过它来管理代码仓库，并自动实现 PR 的管理。\\n\\n![ag-cli 配置](assets/image-20260423142209473.png)\\n\\n可以参考文档在系统中安装 `ag-cli`，也可以直接将文档提供给 **JiuwenSwarm** 进行安装。\\n\\n![安装 ag-cli](assets/image-20260423142421574.png)\\n\\n安装到最后，需要手动进行授权。\\n\\n![授权步骤 1](assets/image-20260423142454316.png)\\n\\n![授权步骤 2](assets/image-20260423142517587.png)\\n\\n### 模拟生成 PR\\n\\n> PR 的生成主要演示了 **JiuwenSwarm** 有能力接管 **AtomGit**。\\n\\n![PR 生成演示 1](assets/image-20260423144337786.png)\\n\\n![PR 生成演示 2](assets/image-20260423144352415.png)\\n\\n## 自动生成飞书日报\\n\\n> **参考文档**：[飞书 CLI 官方文档](https://open.larksuite.com/document/mcp_open_tools/feishu-cli-let-ai-actually-do-your-work-in-feishu)\\n\\n![飞书日报](assets/image-20260423145550856.png)\\n\\n飞书推出了 `lark-cli` 终端工具，可以在 **JiuwenSwarm** 中接入和使用。接入后，**JiuwenSwarm** 便具备了操作飞书文档的能力。\\n\\n当然，**JiuwenSwarm** 本身已接入飞书机器人，也可以直接给该机器人开通相关权限来操作飞书文档。\\n\\n### JiuwenSwarm 接入飞书 lark-cli\\n\\n![接入 lark-cli](assets/image-20260423145053102.png)\\n\\n### 授权给 lark-cli\\n\\n![授权步骤 1](assets/image-20260423145139940.png)\\n\\n![授权步骤 2](assets/image-20260423145221387.png)\\n\\n## 总结\\n\\n通过 **JiuwenSwarm AgentSwarm** 的 Leader-Teammate 协作框架，我们可以轻松打造一支 **7×24 小时在线的自动化研发团队**。从需求拆解、任务分配到执行汇报，Leader 与 Teammate 之间的高效协同，让复杂项目的推进变得井然有序。\\n\\n本文以三大实战场景为例——**字幕软件开发**、**AtomGit Issue/PR 智能化处理**、**飞书文档同步与日报生成**——展示了 AgentSwarms 在真实研发流程中的落地价值。借助飞书机器人作为交互入口，结合 `ag-cli` 和 `lark-cli` 等工具链，AI Agent 不仅能写代码，还能管理代码仓库、操作协作平台，真正融入团队的工作流。\\n\\n未来，随着 AgentSwarms 在更多业务场景中的深入应用，人机协作的研发模式将成为提升团队效率的关键杠杆。\\n\\n## 相关引用\\n\\n1. [https://atomgit.com/openJiuwen](https://atomgit.com/openJiuwen?utm_source=csdn) **欢迎 star**\\n2. [https://www.openjiuwen.com](https://www.openjiuwen.com?utm_source=csdn)\\n"}'),G={name:"AI人工智能/基于 JiuwenSwarm AgentSwarm 构建自动化研发团队/基于 JiuwenSwarm AgentSwarm 构建自动化研发团队.md"};function v(D,n,B,W,j,y){return a(),t("div",null,[...n[0]||(n[0]=[s('<h1 id="利用-jiuwenswarm-agentswarm-打造自动化研发团队" tabindex="-1">利用 JiuwenSwarm AgentSwarm 打造自动化研发团队 <a class="header-anchor" href="#利用-jiuwenswarm-agentswarm-打造自动化研发团队" aria-label="Permalink to &quot;利用 JiuwenSwarm AgentSwarm 打造自动化研发团队&quot;">​</a></h1><blockquote><p>本文介绍如何通过 <strong>JiuwenSwarm AgentSwarm</strong> 构建自动化研发团队，实现字幕软件开发、AtomGit Issue/PR 智能处理与飞书文档同步。</p></blockquote><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#JiuwenSwarm-平台概述">JiuwenSwarm 平台概述</a><ul><li><a href="#系统架构">系统架构</a></li><li><a href="#预置智能体类型">预置智能体类型</a></li></ul></li><li><a href="#什么是-AgentSwarms">什么是 AgentSwarms</a></li><li><a href="#飞书群中添加机器人">飞书群中添加机器人</a></li><li><a href="#开启-AgentSwarms">开启 AgentSwarms</a></li><li><a href="#工作流程">工作流程</a></li><li><a href="#自动处理-pr">自动处理 PR</a><ul><li><a href="#模拟生成-pr">模拟生成 PR</a></li></ul></li><li><a href="#自动生成飞书日报">自动生成飞书日报</a><ul><li><a href="#JiuwenSwarm-接入飞书-lark-cli">JiuwenSwarm 接入飞书 lark-cli</a></li><li><a href="#授权给-lark-cli">授权给 lark-cli</a></li></ul></li><li><a href="#总结">总结</a></li></ul><h2 id="jiuwenswarm-平台概述" tabindex="-1">JiuwenSwarm 平台概述 <a class="header-anchor" href="#jiuwenswarm-平台概述" aria-label="Permalink to &quot;JiuwenSwarm 平台概述&quot;">​</a></h2><p><strong>openJiuwen</strong> 是一个开源的 AI Agent 平台，其核心目标是为开发者提供灵活、强大且易于使用的 AI Agent 开发与运行环境。</p><p>借助这一平台，开发者能够迅速搭建起可处理各种复杂度的 AI Agent，实现多个 Agent 之间的协作互动，从而高效地打造出生产级别的可靠 AI Agent。同时，该平台也帮助企业和个人用户快速构建自己的 AI Agent 系统或平台，促进商用级 Agentic AI 技术的广泛落地应用。</p><h3 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h3><p>openJiuwen 的整体架构由三大核心模块构成：<strong>openJiuwen Core</strong>、<strong>openJiuwen Studio</strong> 以及 <strong>openJiuwen Ops</strong>。</p><p><img src="'+r+'" alt="系统架构图"></p><p>在开发阶段，openJiuwen 提供了 Agent 编排与构建能力，让开发者能够快速创建 Agent 并进行高效开发。</p><h3 id="预置智能体类型" tabindex="-1">预置智能体类型 <a class="header-anchor" href="#预置智能体类型" aria-label="Permalink to &quot;预置智能体类型&quot;">​</a></h3><p>目前，openJiuwen 提供了两种预置智能体类型，为用户提供丰富的功能和灵活的开发选项，以适应不同场景下的智能化需求：</p><ul><li><p><strong>ReActAgent</strong>：这是一种基于 ReAct（推理 + 行动）规划范式的 Agent。它通过「思考 → 行动 → 观察」的循环迭代过程来完成任务。ReActAgent 拥有强大的多轮推理和自我纠错能力，能够进行动态决策并灵活适应环境变化，特别适合那些需要复杂推理和策略调整的任务场景。</p><p><img src="'+i+'" alt="ReActAgent 架构"></p></li><li><p><strong>Workflow Agent</strong>：这是一种面向多步骤任务的流程自动化 Agent，严格按照用户预设的任务流程来高效执行复杂任务。它强调通过预定义流程实现任务的规范化与高效执行，适用于任务结构清晰、能够分解为多个明确步骤的场景。</p><p><img src="'+o+'" alt="Workflow Agent 架构"></p></li></ul><h2 id="jiuwenswarm-概述" tabindex="-1">JiuwenSwarm 概述 <a class="header-anchor" href="#jiuwenswarm-概述" aria-label="Permalink to &quot;JiuwenSwarm 概述&quot;">​</a></h2><p>​ 它是一款基于 openJiuwen Python 框架开发的 AI Agent，天然拥有良好的生态兼容性和扩展能力。在模型接入方面，JiuwenSwarm 支持华为云 MaaS 等主流模型平台，用户只需简单配置即可调用华为云的模型服务。此外，JiuwenSwarm 已实现与小艺开放平台的无缝对接，华为手机用户可以通过小艺直接唤醒并使用 JiuwenSwarm，享受随叫随到的智能服务。</p><p><img src="'+g+'" alt=""></p><h2 id="什么是-agentswarms" tabindex="-1">什么是 AgentSwarms <a class="header-anchor" href="#什么是-agentswarms" aria-label="Permalink to &quot;什么是 AgentSwarms&quot;">​</a></h2><p>​ 从 Prompt Engineering（提示工程）、Context Engineering（语境工程）演进至当下备受瞩目的 Harness Engineering（驾驭工程），AI 领域的工程范式始终处于高速迭代之中。</p><p>​ 目前，针对单一智能体的“驾驭与治理”已逐渐成为行业标配，但如何让多个智能体仿若一支精锐团队，实现自主分工、高效沟通与无缝协作，依然是横亘在行业面前的核心挑战。</p><p>​ 恰逢这一趋势风口，获华为支持的 openJiuwen 社区正式发布了最新的 JiuwenSwarm 版本。该版本重磅新增了对 AgentSwarm 多智能体协同能力的支持，并前瞻性地提出 Harness Engineering 的下一个演进方向是“Coordination Engineering（协同工程）”，成功将多智</p><p>能体自主协同从抽象的概念转化为可直接落地的实战场景。</p><p><img src="'+m+'" alt=""></p><h2 id="飞书群中添加机器人" tabindex="-1">飞书群中添加机器人 <a class="header-anchor" href="#飞书群中添加机器人" aria-label="Permalink to &quot;飞书群中添加机器人&quot;">​</a></h2><blockquote><p><strong>参考文档</strong>：<a href="https://gitcode.com/openJiuwen/JiuwenSwarm/blob/develop/docs/zh/%E9%A2%91%E9%81%93.md#%E9%A3%9E%E4%B9%A6" target="_blank" rel="noreferrer">飞书频道配置指南</a></p></blockquote><p>在飞书群聊中，添加创建好的飞书机器人后，用户可以直接在群聊中对话。飞书机器人负责接收用户的指令，并代理用户与 <strong>JiuwenSwarm</strong> 进行交互。</p><p><img src="'+p+'" alt="飞书群机器人"></p><h2 id="开启-agentswarms" tabindex="-1">开启 AgentSwarms <a class="header-anchor" href="#开启-agentswarms" aria-label="Permalink to &quot;开启 AgentSwarms&quot;">​</a></h2><p>在飞书对话中，输入以下命令即可主动开启 AgentSwarms 模式：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> team</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后可以直接输入需求来安排任务。</p><p><img src="'+l+'" alt="开启 AgentSwarms 模式"></p><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h2><p>整体工作流程如下图所示：</p><p><img src="'+w+'" alt="工作流程概览"></p><p>AgentSwarms 的标准协作流程包含以下步骤：</p><ol><li><strong>Leader</strong> 接收到任务后，开始拆分任务</li><li><strong>Leader</strong> 布置任务</li><li><strong>Teammate</strong> 认领任务</li><li><strong>Teammate</strong> 执行任务</li><li><strong>Leader</strong> 和 <strong>Teammate</strong> 之间相互通信</li><li><strong>Teammate</strong> 汇报任务进度</li><li><strong>Leader</strong> 总结工作</li></ol><p>以下是各阶段的操作截图：</p><p><strong>步骤 1-2：任务拆分与布置</strong></p><p><img src="'+c+'" alt="Leader 拆分任务"></p><p><strong>步骤 3-4：任务认领与执行</strong></p><p><img src="'+u+'" alt="Teammate 执行任务"></p><p><img src="'+h+'" alt="任务执行中"></p><p><img src="'+d+'" alt="任务执行过程"></p><p><img src="'+A+'" alt="代码生成"></p><p><img src="'+S+'" alt="持续执行"></p><p><strong>步骤 5-6：通信与汇报</strong></p><p><img src="'+_+'" alt="通信汇报"></p><p><img src="'+J+'" alt="任务汇报"></p><p><strong>步骤 7：总结</strong></p><p><img src="'+k+'" alt="Leader 总结"></p><h3 id="结束" tabindex="-1">结束 <a class="header-anchor" href="#结束" aria-label="Permalink to &quot;结束&quot;">​</a></h3><p>当所有任务完成后，Leader 会输出最终的总结报告。</p><p><img src="'+b+'" alt="任务结束"></p><h2 id="自动处理-pr" tabindex="-1">自动处理 PR <a class="header-anchor" href="#自动处理-pr" aria-label="Permalink to &quot;自动处理 PR&quot;">​</a></h2><blockquote><p><strong>工具地址</strong>：<a href="https://atomgit.com/GitCode/ag-cli" target="_blank" rel="noreferrer">https://atomgit.com/GitCode/ag-cli</a></p></blockquote><blockquote><p>可以在 <strong>JiuwenSwarm</strong> 中配置 <strong>AtomGit</strong> 的 CLI 工具，设置监听后自动处理审核和合并 PR。</p><p>⚠️ <strong>注意</strong>：监听需要提供公网域名，用来接收 AtomGit 的 Webhooks 通知。</p></blockquote><p><strong>AtomGit</strong> 提供了 <code>ag-cli</code> 工具，可以在 <strong>JiuwenSwarm</strong> 中接入。接入后，<strong>AgentSwarms</strong> 即可通过它来管理代码仓库，并自动实现 PR 的管理。</p><p><img src="'+f+'" alt="ag-cli 配置"></p><p>可以参考文档在系统中安装 <code>ag-cli</code>，也可以直接将文档提供给 <strong>JiuwenSwarm</strong> 进行安装。</p><p><img src="'+q+'" alt="安装 ag-cli"></p><p>安装到最后，需要手动进行授权。</p><p><img src="'+P+'" alt="授权步骤 1"></p><p><img src="'+R+'" alt="授权步骤 2"></p><h3 id="模拟生成-pr" tabindex="-1">模拟生成 PR <a class="header-anchor" href="#模拟生成-pr" aria-label="Permalink to &quot;模拟生成 PR&quot;">​</a></h3><blockquote><p>PR 的生成主要演示了 <strong>JiuwenSwarm</strong> 有能力接管 <strong>AtomGit</strong>。</p></blockquote><p><img src="'+I+'" alt="PR 生成演示 1"></p><p><img src="'+C+'" alt="PR 生成演示 2"></p><h2 id="自动生成飞书日报" tabindex="-1">自动生成飞书日报 <a class="header-anchor" href="#自动生成飞书日报" aria-label="Permalink to &quot;自动生成飞书日报&quot;">​</a></h2><blockquote><p><strong>参考文档</strong>：<a href="https://open.larksuite.com/document/mcp_open_tools/feishu-cli-let-ai-actually-do-your-work-in-feishu" target="_blank" rel="noreferrer">飞书 CLI 官方文档</a></p></blockquote><p><img src="'+x+'" alt="飞书日报"></p><p>飞书推出了 <code>lark-cli</code> 终端工具，可以在 <strong>JiuwenSwarm</strong> 中接入和使用。接入后，<strong>JiuwenSwarm</strong> 便具备了操作飞书文档的能力。</p><p>当然，<strong>JiuwenSwarm</strong> 本身已接入飞书机器人，也可以直接给该机器人开通相关权限来操作飞书文档。</p><h3 id="jiuwenswarm-接入飞书-lark-cli" tabindex="-1">JiuwenSwarm 接入飞书 lark-cli <a class="header-anchor" href="#jiuwenswarm-接入飞书-lark-cli" aria-label="Permalink to &quot;JiuwenSwarm 接入飞书 lark-cli&quot;">​</a></h3><p><img src="'+E+'" alt="接入 lark-cli"></p><h3 id="授权给-lark-cli" tabindex="-1">授权给 lark-cli <a class="header-anchor" href="#授权给-lark-cli" aria-label="Permalink to &quot;授权给 lark-cli&quot;">​</a></h3><p><img src="'+T+'" alt="授权步骤 1"></p><p><img src="'+L+'" alt="授权步骤 2"></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>通过 <strong>JiuwenSwarm AgentSwarm</strong> 的 Leader-Teammate 协作框架，我们可以轻松打造一支 <strong>7×24 小时在线的自动化研发团队</strong>。从需求拆解、任务分配到执行汇报，Leader 与 Teammate 之间的高效协同，让复杂项目的推进变得井然有序。</p><p>本文以三大实战场景为例——<strong>字幕软件开发</strong>、<strong>AtomGit Issue/PR 智能化处理</strong>、<strong>飞书文档同步与日报生成</strong>——展示了 AgentSwarms 在真实研发流程中的落地价值。借助飞书机器人作为交互入口，结合 <code>ag-cli</code> 和 <code>lark-cli</code> 等工具链，AI Agent 不仅能写代码，还能管理代码仓库、操作协作平台，真正融入团队的工作流。</p><p>未来，随着 AgentSwarms 在更多业务场景中的深入应用，人机协作的研发模式将成为提升团队效率的关键杠杆。</p><h2 id="相关引用" tabindex="-1">相关引用 <a class="header-anchor" href="#相关引用" aria-label="Permalink to &quot;相关引用&quot;">​</a></h2><ol><li><a href="https://atomgit.com/openJiuwen?utm_source=csdn" target="_blank" rel="noreferrer">https://atomgit.com/openJiuwen</a> <strong>欢迎 star</strong></li><li><a href="https://www.openjiuwen.com?utm_source=csdn" target="_blank" rel="noreferrer">https://www.openjiuwen.com</a></li></ol>',84)])])}const O=e(G,[["render",v]]);export{H as __pageData,O as default};
